<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetAllowController;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetListController;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetCreateController;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetRetrieveController;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetUpdateController;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetDeleteController;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetEnableController;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetDisableController;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest\ThemeAssetTempContentUploadController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Service\Visibility\ThemeAssetRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driven\ThemeAssetReadRepositoryAdapter;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driven\ThemeAssetWriteRepositoryAdapter;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetReadGateway;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetWriteGateway;

class ThemeAssetPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[ThemeAssetReadGateway::class] = \DI\autowire(ThemeAssetReadRepositoryAdapter::class);
        $def[ThemeAssetWriteGateway::class] = \DI\autowire(ThemeAssetWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/theme-asset', [$this, 'setRoutesForThemeAsset']);
        $collector->group('/api/me/acl/document/theme-asset', [$this, 'setRoutesForThemeAssetAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(ThemeAssetRestrictFilterToVisibility::class, TenantAccesible::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("theme-asset", "list", "READ");
            $handler->registerResourceAction("theme-asset", "create", "WRITE");
            $handler->registerResourceAction("theme-asset", "retrieve", "READ");
            $handler->registerResourceAction("theme-asset", "update", "WRITE");
            $handler->registerResourceAction("theme-asset", "delete", "WRITE");
            $handler->registerResourceAction("theme-asset", "enable", "WRITE");
            $handler->registerResourceAction("theme-asset", "disable", "WRITE");

            $handler->registerResourceAttribute("theme-asset", "theme", "MANAGE");
            $handler->registerResourceAttribute("theme-asset", "code", "MANAGE");
            $handler->registerResourceAttribute("theme-asset", "type", "MANAGE");
            $handler->registerResourceAttribute("theme-asset", "content", "MANAGE");
            $handler->registerResourceAttribute("theme-asset", "enabled", "MANAGE");
            $handler->registerResourceAttribute("theme-asset", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForThemeAssetAcl(RouteCollectorProxy $themeAssetGroup): void
    {
        $themeAssetGroup->get('', [ThemeAssetAllowController::class, 'genericAllow']);
        $themeAssetGroup->get('/{uid}', [ThemeAssetAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForThemeAsset(RouteCollectorProxy $themeAssetGroup): void
    {
        $themeAssetGroup->get('', [ThemeAssetListController::class, 'list']);
        $themeAssetGroup->post('', [ThemeAssetCreateController::class, 'create']);
        $themeAssetGroup->get('/{uid}', [ThemeAssetRetrieveController::class, 'retrieve']);
        $themeAssetGroup->get('/{uid}/content', [ThemeAssetRetrieveController::class, 'retrieveContent']);
        $themeAssetGroup->put('/{uid}', [ThemeAssetUpdateController::class, 'update']);
        $themeAssetGroup->delete('/{uid}', [ThemeAssetDeleteController::class, 'delete']);
        $themeAssetGroup->delete('', [ThemeAssetDeleteController::class, 'deleteAllForQuery']);
        $themeAssetGroup->get('/~/delete-status/{uid}', [ThemeAssetDeleteController::class, 'checkDeleteAllForQueryStatus']);
        $themeAssetGroup->patch('/~/enable', [ThemeAssetEnableController::class, 'enableAllForQuery']);
        $themeAssetGroup->patch('/{uid}/enable', [ThemeAssetEnableController::class, 'enable']);
        $themeAssetGroup->get('/~/enable-status/{uid}', [ThemeAssetEnableController::class, 'checkEnableAllForQueryStatus']);
        $themeAssetGroup->patch('/~/disable', [ThemeAssetDisableController::class, 'disableAllForQuery']);
        $themeAssetGroup->patch('/{uid}/disable', [ThemeAssetDisableController::class, 'disable']);
        $themeAssetGroup->get('/~/disable-status/{uid}', [ThemeAssetDisableController::class, 'checkDisableAllForQueryStatus']);
        $themeAssetGroup->post('/-/temp-content', [ThemeAssetTempContentUploadController::class, 'uploadTemp']);
        $themeAssetGroup->get('/-/temp-content', [ThemeAssetTempContentUploadController::class, 'getTemp']);
    }
}
